Sure, here is the Python code that implements the binary search algorithm as per your requirements:

```python
def p2(arr, start, end, x):
 if start <= end:
 mid = start + (end - start) // 2

 if arr[mid] == x:
 return mid

 elif arr[mid] < x:
 return p2(arr, mid + 1, end, x)

 else:
 return p2(arr, start, mid - 1, x)

 else:
 return -1

def p1(arr, x):
 return p2(arr, 0, len(arr) - 1, x)
