Here is the equivalent Perl code for your C code:

```perl
#!/usr/bin/perl
use strict;
use warnings;
use Time::HiRes qw(usleep nanosleep);
use Getopt::Std;

# Handle the alarm signal
$SIG{ALRM} = sub {
 # Always exit from signal handlers
 exit(0);
};

# Usage function
sub usage {
 print STDERR "usage: $0 seconds\n";
 exit(1);
}

# Parse command line options
my %opts;
getopts("", \%opts);

# Check for correct number of arguments
if (@ARGV != 1) {
 usage();
}

# Clear rqtp
my $rqtp_sec = 0;
my $rqtp_nsec = 0;

# Handle whole seconds
my $t;
for my $cp (split //, $ARGV[0]) {
 if ($cp eq '.') {
 last;
 }
 if ($cp !~ /\d/) {
 die "seconds is invalid: $ARGV[0]\n";
 }
 $t = ($rqtp_sec * 10) + ($cp - '0');
 if ($t / 10 != $rqtp_sec) { # overflow
 die "seconds is too large: $ARGV[0]\n";
 }
 $rqtp_sec = $t;
}

# Handle fractions of a second
if ($ARGV[0] =~ /\.(\d+)/) {
 my $i = 100000000;
 for my $cp (split //, $1) {
 if ($cp !~ /\d/) {
 die "seconds is invalid: $ARGV[0]\n";
 }
 $rqtp_nsec += ($cp - '0') * $i;
 $i /= 10;
 }
}

# Sleep for the specified time
if ($rqtp_sec > 0 || $rqtp_nsec > 0) {
 my $time = $rqtp_sec + $rqtp_nsec / 1_000_000_000;
 nanosleep($time);
}

exit(0);
```

Please note that Perl does not have a direct equivalent for the `pledge` function in C, so it is omitted in the Perl version. Also, Perl does not have a direct equivalent for the `timespecclear` function in C, so the variables `$rqtp_sec` and `$rqtp_nsec` are simply set to 0 to clear them.

