```swift
import Foundation

func countVowelsAndConsonants(input: String) {
 let vowels = CharacterSet(charactersIn: "aeiouAEIOU")
 let consonants = CharacterSet(charactersIn: "bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ")
 let punctuation = CharacterSet.punctuationCharacters
 let whitespace = CharacterSet.whitespacesAndNewlines

 var vowelCount = 0
 var consonantCount = 0
 var characterCount = 0

 for char in input.unicodeScalars {
 if vowels.contains(char) {
 vowelCount += 1
 characterCount += 1
 } else if consonants.contains(char) {
 consonantCount += 1
 characterCount += 1
 } else if punctuation.contains(char) || whitespace.contains(char) {
 continue
 }
 }

 print("Number of vowels: \(vowelCount)")
 print("Number of consonants: \(consonantCount)")
 print("Total number of characters: \(characterCount)")
}

let sentence = "Your sentence goes here!"
countVowelsAndConsonants(input: sentence)
```

You can replace "Your sentence goes here!" with any sentence you want to analyze. The function `countVowelsAndConsonants` will count the number of vowels, consonants, and total characters (excluding whitespace and punctuation), and print the results.

Sure, here is a simple implementation of a Suffix Array in C++ that can perform substring search and suffix search operations efficiently. 

```cpp
#include <iostream>
#include <algorithm>
#include <cstring>
using namespace std;

#define MAXN 1000

string txt;
int N, c[MAXN], temp[MAXN], pos[MAXN], suffix[MAXN];

bool equal(int i, int j, int l) {
 return temp[i] == temp[j] && temp[i + l] == temp[j + l];
}

void build_suffix_array() {
 N = txt.size();
 for (int i = 0; i < N; i++) suffix[i] = i, pos[i] = txt[i];
 for (int gap = 1;; gap *= 2) {
 auto cmp = [gap](int i, int j) {
 if (pos[i] != pos[j]) return pos[i] < pos[j];
 i += gap; j += gap;
 return (i < N && j < N) ? pos[i] < pos[j] : i > j;
 };
 sort(suffix, suffix + N, cmp);
 for (int i = 0; i < N - 1; i++) temp[i + 1] = temp[i] + cmp(suffix[i], suffix[i + 1]);
 for (int i = 0; i < N; i++) pos[suffix[i]] = temp[i];
 if (temp[N - 1] == N - 1) break;
 }
}

bool substring_search(string pattern) {
 int m = pattern.size();
 int l = 0, r = N - 1;
 while (l <= r) {
 int mid = l + (r - l) / 2;
 string str = txt.substr(suffix[mid], m);
 if (str == pattern) return true;
 else if (str < pattern) l = mid + 1;
 else r = mid - 1;
 }
 return false;
}

bool suffix_search(string pattern) {
 int m = pattern.size();
 for (int i = 0; i < N; i++) {
 string str = txt.substr(suffix[i]);
 if (str.substr(0, m) == pattern) return true;
 }
 return false;
}

int main() {
 txt = "banana";
 build_suffix_array();
 cout << (substring_search("ana") ? "Found" : "Not Found") << endl;
 cout << (suffix_search("na") ? "Found" : "Not Found") << endl;
 return 0;
}
```

This code first builds a suffix array for the given text. The `build_suffix_array` function sorts all the suffixes of the text. Then, it uses binary search in the `substring_search` function to find if a pattern is a substring of the text. The `suffix_search` function checks if a pattern is a suffix of any of the suffixes of the text. 

Please note that this is a simple implementation and may not handle all edge cases. You may need to modify and optimize it according to your specific needs.

You can achieve this by using the `indexOf` method to check if the '@' character exists in the string, and then using `substring` or `slice` to remove everything before '@'. If '@' does not exist in the string, you can simply prepend it to the string. Here is a JavaScript function that implements this:

```javascript
function processValue(value) {
 var atIndex = value.indexOf('@');

 if (atIndex !== -1) {
 // '@' exists, remove everything before it
 return value.substring(atIndex);
 } else {
 // '@' does not exist, prepend it to the string
 return '@' + value;
 }
}
```

You can use this function like this:

```javascript
console.log(processValue('hello@world')); // Outputs: '@world'
console.log(processValue('helloworld')); // Outputs: '@helloworld'
```

